\newcommand{\tikzpeople@businessman@paint}{
	\tikzpeople@person@paintshirt
	\tikzpeople@businessman@paintundershirt
	\tikzpeople@businessman@paintopenshirt
	\tikzpeople@person@paintrighthorn
