		\begin{scope}
			\clip (0.1pt,2.9pt) ellipse (2.8pt and 0.8pt);
			\draw[hat,shading angle=-45] (0.1pt,2.4pt) ellipse (2pt and 0.7pt);
		\end{scope}
		\draw[details] (0.1pt,3.2pt) ellipse (0.8pt and 0.55pt);
	}
}

