\newcommand{\tikzpeople@santa@definestyles}{
	\if@tikzpeople@saturated
		\tikzset{
			details/.style={color=\tikzpeople@details,top color=\tikzpeople@details!60, bottom color=\tikzpeople@details,shading angle=45},
